// Work MVP 데이터 관리 훅
import { useState, useEffect, useCallback } from 'react';
import * as store from '../stores/workFirestore';
import * as scheduleStore from '../stores/firestore';
import type { Project, ProjectTask, ProjectTodo } from '../types/work';
import type { ScheduleEvent, TodoItem } from '../types';
import { scheduleEventsToTaskViews, todoItemsToTodoViews } from '../utils/scheduleAdapter';

// ===== Projects Hook =====

export function useProjects() {
  const [projects, setProjects] = useState<Project[]>([]);
  const [archivedProjects, setArchivedProjects] = useState<Project[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  // 데이터 로드
  const loadProjects = useCallback(async () => {
    setIsLoading(true);
    try {
      const [active, archived] = await Promise.all([
        store.getActiveProjects(),
        store.getArchivedProjects(),
      ]);
      setProjects(active);
      setArchivedProjects(archived);
    } catch (error) {
      console.error('Failed to load projects:', error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    loadProjects();
  }, [loadProjects]);

  // 프로젝트 생성
  const createProject = useCallback(async (title: string, color: string = '#a5b4fc') => {
    try {
      const priorityIndex = await store.getNextProjectPriorityIndex();
      const now = Date.now();
      
      const project: Project = {
        id: store.generateId('proj'),
        userId: '', // Firestore에서 자동 설정됨
        title,
        color,
        start_at: null,
        end_at: null,
        due_at: null,
        is_all_day: false,
        status: 'ACTIVE',
        priority_order_index: priorityIndex,
        created_at: now,
        updated_at: now,
        archived_at: null,
      };

      await store.saveProject(project);
      setProjects(prev => [project, ...prev]);
      return project;
    } catch (error) {
      console.error('Failed to create project:', error);
      throw error;
    }
  }, []);

  // 프로젝트 업데이트
  const updateProject = useCallback(async (project: Project) => {
    try {
      const updated = { ...project, updated_at: Date.now() };
      await store.saveProject(updated);
      setProjects(prev => prev.map(p => p.id === project.id ? updated : p));
      return updated;
    } catch (error) {
      console.error('Failed to update project:', error);
      throw error;
    }
  }, []);

  // 프로젝트 아카이브
  const archiveProject = useCallback(async (projectId: string) => {
    try {
      await store.archiveProject(projectId);
      const project = projects.find(p => p.id === projectId);
      if (project) {
        const archived = { ...project, status: 'ARCHIVED' as const, archived_at: Date.now() };
        setProjects(prev => prev.filter(p => p.id !== projectId));
        setArchivedProjects(prev => [archived, ...prev]);
      }
    } catch (error) {
      console.error('Failed to archive project:', error);
      throw error;
    }
  }, [projects]);

  // 프로젝트 영구 삭제
  const deleteProjectForever = useCallback(async (projectId: string) => {
    try {
      await store.deleteProjectForever(projectId);
      setProjects(prev => prev.filter(p => p.id !== projectId));
      setArchivedProjects(prev => prev.filter(p => p.id !== projectId));
    } catch (error) {
      console.error('Failed to delete project:', error);
      throw error;
    }
  }, []);

  // 프로젝트 순서 변경 (드래그 정렬)
  const reorderProjects = useCallback(async (projectIds: string[]) => {
    try {
      // 낙관적 업데이트
      const reordered = projectIds.map((id, index) => {
        const project = projects.find(p => p.id === id);
        return project ? { ...project, priority_order_index: (index + 1) * 1000 } : null;
      }).filter((p): p is Project => p !== null);
      
      setProjects(reordered);
      await store.reorderProjects(projectIds);
    } catch (error) {
      console.error('Failed to reorder projects:', error);
      // 실패 시 다시 로드
      loadProjects();
      throw error;
    }
  }, [projects, loadProjects]);

  return {
    projects,
    archivedProjects,
    isLoading,
    createProject,
    updateProject,
    archiveProject,
    deleteProjectForever,
    reorderProjects,
    refreshProjects: loadProjects,
  };
}

// ===== Tasks Hook =====

export function useTasks(projectId?: string | null) {
  const [tasks, setTasks] = useState<ProjectTask[]>([]);
  const [doneTasks, setDoneTasks] = useState<ProjectTask[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const loadTasks = useCallback(async () => {
    setIsLoading(true);
    try {
      let active: ProjectTask[];
      let done: ProjectTask[];

      if (projectId) {
        const allTasks = await store.getTasksByProject(projectId);
        active = allTasks.filter(t => t.status === 'ACTIVE');
        done = allTasks.filter(t => t.status === 'DONE');
      } else {
        [active, done] = await Promise.all([
          store.getActiveTasks(),
          store.getDoneTasks(),
        ]);
      }

      setTasks(active);
      setDoneTasks(done);
    } catch (error) {
      console.error('Failed to load tasks:', error);
    } finally {
      setIsLoading(false);
    }
  }, [projectId]);

  useEffect(() => {
    loadTasks();
  }, [loadTasks]);

  const createTask = useCallback(async (title: string, taskProjectId: string | null = null) => {
    try {
      const priorityIndex = await store.getNextTaskPriorityIndex();
      const now = Date.now();

      const task: ProjectTask = {
        id: store.generateId('task'),
        projectId: taskProjectId,
        title,
        start_at: null,
        end_at: null,
        due_at: null,
        is_all_day: false,
        status: 'ACTIVE',
        completed_at: null,
        priority_order_index: priorityIndex,
        unscheduled_order_index: 0,
        created_at: now,
        updated_at: now,
      };

      await store.saveTask(task);
      setTasks(prev => [task, ...prev]);
      return task;
    } catch (error) {
      console.error('Failed to create task:', error);
      throw error;
    }
  }, []);

  const updateTask = useCallback(async (task: ProjectTask) => {
    try {
      const updated = { ...task, updated_at: Date.now() };
      await store.saveTask(updated);
      setTasks(prev => prev.map(t => t.id === task.id ? updated : t));
      return updated;
    } catch (error) {
      console.error('Failed to update task:', error);
      throw error;
    }
  }, []);

  const completeTask = useCallback(async (taskId: string) => {
    try {
      await store.completeTask(taskId);
      const task = tasks.find(t => t.id === taskId);
      if (task) {
        const completed = { ...task, status: 'DONE' as const, completed_at: Date.now() };
        setTasks(prev => prev.filter(t => t.id !== taskId));
        setDoneTasks(prev => [completed, ...prev]);
      }
    } catch (error) {
      console.error('Failed to complete task:', error);
      throw error;
    }
  }, [tasks]);

  const undoCompleteTask = useCallback(async (taskId: string) => {
    try {
      await store.undoCompleteTask(taskId);
      const task = doneTasks.find(t => t.id === taskId);
      if (task) {
        const active = { ...task, status: 'ACTIVE' as const, completed_at: null };
        setDoneTasks(prev => prev.filter(t => t.id !== taskId));
        setTasks(prev => [active, ...prev]);
      }
    } catch (error) {
      console.error('Failed to undo complete task:', error);
      throw error;
    }
  }, [doneTasks]);

  const deleteTask = useCallback(async (taskId: string) => {
    try {
      await store.deleteTask(taskId);
      setTasks(prev => prev.filter(t => t.id !== taskId));
      setDoneTasks(prev => prev.filter(t => t.id !== taskId));
    } catch (error) {
      console.error('Failed to delete task:', error);
      throw error;
    }
  }, []);

  const reorderTasks = useCallback(async (taskIds: string[]) => {
    try {
      const reordered = taskIds.map((id, index) => {
        const task = tasks.find(t => t.id === id);
        return task ? { ...task, priority_order_index: (index + 1) * 1000 } : null;
      }).filter((t): t is ProjectTask => t !== null);

      setTasks(reordered);
      await store.reorderTasks(taskIds);
    } catch (error) {
      console.error('Failed to reorder tasks:', error);
      loadTasks();
      throw error;
    }
  }, [tasks, loadTasks]);

  return {
    tasks,
    doneTasks,
    isLoading,
    createTask,
    updateTask,
    completeTask,
    undoCompleteTask,
    deleteTask,
    reorderTasks,
    refreshTasks: loadTasks,
  };
}

// ===== Todos Hook =====

export function useProjectTodos(taskId?: string | null) {
  const [todos, setTodos] = useState<ProjectTodo[]>([]);
  const [doneTodos, setDoneTodos] = useState<ProjectTodo[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const loadTodos = useCallback(async () => {
    setIsLoading(true);
    try {
      let active: ProjectTodo[];
      let done: ProjectTodo[];

      if (taskId) {
        const allTodos = await store.getTodosByTask(taskId);
        active = allTodos.filter(t => !t.is_done);
        done = allTodos.filter(t => t.is_done);
      } else {
        [active, done] = await Promise.all([
          store.getActiveTodos(),
          store.getDoneTodos(),
        ]);
      }

      setTodos(active);
      setDoneTodos(done);
    } catch (error) {
      console.error('Failed to load todos:', error);
    } finally {
      setIsLoading(false);
    }
  }, [taskId]);

  useEffect(() => {
    loadTodos();
  }, [loadTodos]);

  const createTodo = useCallback(async (content: string, todoTaskId: string | null = null) => {
    try {
      const priorityIndex = await store.getNextTodoPriorityIndex(todoTaskId);
      const now = Date.now();

      const todo: ProjectTodo = {
        id: store.generateId('todo'),
        taskId: todoTaskId,
        content,
        start_at: null,
        end_at: null,
        due_at: null,
        is_all_day: false,
        is_done: false,
        completed_at: null,
        priority_order_index: priorityIndex,
        unscheduled_order_index: 0,
        created_at: now,
        updated_at: now,
      };

      await store.saveProjectTodo(todo);
      setTodos(prev => [todo, ...prev]);
      return todo;
    } catch (error) {
      console.error('Failed to create todo:', error);
      throw error;
    }
  }, []);

  const updateTodo = useCallback(async (todo: ProjectTodo) => {
    try {
      const updated = { ...todo, updated_at: Date.now() };
      await store.saveProjectTodo(updated);
      setTodos(prev => prev.map(t => t.id === todo.id ? updated : t));
      return updated;
    } catch (error) {
      console.error('Failed to update todo:', error);
      throw error;
    }
  }, []);

  const completeTodo = useCallback(async (todoId: string) => {
    try {
      await store.completeProjectTodo(todoId);
      const todo = todos.find(t => t.id === todoId);
      if (todo) {
        const completed = { ...todo, is_done: true, completed_at: Date.now() };
        setTodos(prev => prev.filter(t => t.id !== todoId));
        setDoneTodos(prev => [completed, ...prev]);
      }
    } catch (error) {
      console.error('Failed to complete todo:', error);
      throw error;
    }
  }, [todos]);

  const undoCompleteTodo = useCallback(async (todoId: string) => {
    try {
      await store.undoCompleteProjectTodo(todoId);
      const todo = doneTodos.find(t => t.id === todoId);
      if (todo) {
        const active = { ...todo, is_done: false, completed_at: null };
        setDoneTodos(prev => prev.filter(t => t.id !== todoId));
        setTodos(prev => [active, ...prev]);
      }
    } catch (error) {
      console.error('Failed to undo complete todo:', error);
      throw error;
    }
  }, [doneTodos]);

  const deleteTodo = useCallback(async (todoId: string) => {
    try {
      await store.deleteProjectTodo(todoId);
      setTodos(prev => prev.filter(t => t.id !== todoId));
      setDoneTodos(prev => prev.filter(t => t.id !== todoId));
    } catch (error) {
      console.error('Failed to delete todo:', error);
      throw error;
    }
  }, []);

  const reorderTodos = useCallback(async (todoIds: string[]) => {
    try {
      const reordered = todoIds.map((id, index) => {
        const todo = todos.find(t => t.id === id);
        return todo ? { ...todo, priority_order_index: (index + 1) * 1000 } : null;
      }).filter((t): t is ProjectTodo => t !== null);

      setTodos(reordered);
      await store.reorderTodos(todoIds);
    } catch (error) {
      console.error('Failed to reorder todos:', error);
      loadTodos();
      throw error;
    }
  }, [todos, loadTodos]);

  return {
    todos,
    doneTodos,
    isLoading,
    createTodo,
    updateTodo,
    completeTodo,
    undoCompleteTodo,
    deleteTodo,
    reorderTodos,
    refreshTodos: loadTodos,
  };
}

// ===== 기존 일정 데이터 Hook =====

export type ScheduleTaskView = ProjectTask & { isReadOnly: true; sourceType: 'schedule' };
export type ScheduleTodoView = ProjectTodo & { isReadOnly: true; sourceType: 'todo' };

export function useScheduleEvents() {
  const [events, setEvents] = useState<ScheduleEvent[]>([]);
  const [taskViews, setTaskViews] = useState<ScheduleTaskView[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const loadEvents = useCallback(async () => {
    setIsLoading(true);
    try {
      const allEvents = await scheduleStore.getEvents();
      setEvents(allEvents);
      setTaskViews(scheduleEventsToTaskViews(allEvents));
    } catch (error) {
      console.error('Failed to load schedule events:', error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    loadEvents();
  }, [loadEvents]);

  // 활성/완료 분리
  const activeTaskViews = taskViews.filter(t => t.status === 'ACTIVE');
  const doneTaskViews = taskViews.filter(t => t.status === 'DONE');

  return {
    events,
    taskViews,
    activeTaskViews,
    doneTaskViews,
    isLoading,
    refreshEvents: loadEvents,
  };
}

export function useScheduleTodos() {
  const [todos, setTodos] = useState<TodoItem[]>([]);
  const [todoViews, setTodoViews] = useState<ScheduleTodoView[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const loadTodos = useCallback(async () => {
    setIsLoading(true);
    try {
      const allTodos = await scheduleStore.getTodos();
      setTodos(allTodos);
      setTodoViews(todoItemsToTodoViews(allTodos));
    } catch (error) {
      console.error('Failed to load schedule todos:', error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    loadTodos();
  }, [loadTodos]);

  // 활성/완료 분리
  const activeTodoViews = todoViews.filter(t => !t.is_done);
  const doneTodoViews = todoViews.filter(t => t.is_done);

  return {
    todos,
    todoViews,
    activeTodoViews,
    doneTodoViews,
    isLoading,
    refreshTodos: loadTodos,
  };
}
