// Projects List 모드 컴포넌트
import React, { useState, useRef } from 'react';
import type { Project } from '../../types/work';
import './ProjectList.css';

interface ProjectListProps {
  projects: Project[];
  archivedProjects: Project[];
  showArchived: boolean;
  onCreateProject: (title: string, color: string) => Promise<void>;
  onSelectProject: (project: Project) => void;
  onReorderProjects: (projectIds: string[]) => Promise<void>;
  selectedProjectId?: string | null;
}

const PROJECT_COLORS = [
  '#a5b4fc', '#818cf8', '#6366f1', // indigo
  '#c4b5fd', '#a78bfa', '#8b5cf6', // violet
  '#f0abfc', '#e879f9', '#d946ef', // fuchsia
  '#fda4af', '#fb7185', '#f43f5e', // rose
  '#fcd34d', '#fbbf24', '#f59e0b', // amber
  '#86efac', '#4ade80', '#22c55e', // green
  '#67e8f9', '#22d3ee', '#06b6d4', // cyan
  '#94a3b8', '#64748b', '#475569', // slate
];

export default function ProjectList({
  projects,
  archivedProjects,
  showArchived,
  onCreateProject,
  onSelectProject,
  onReorderProjects,
  selectedProjectId,
}: ProjectListProps) {
  const [newProjectTitle, setNewProjectTitle] = useState('');
  const [selectedColor, setSelectedColor] = useState(PROJECT_COLORS[0]);
  const [isCreating, setIsCreating] = useState(false);
  const [showColorPicker, setShowColorPicker] = useState(false);
  const [draggedId, setDraggedId] = useState<string | null>(null);
  const [dragOverId, setDragOverId] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // 새 프로젝트 생성
  const handleCreateProject = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newProjectTitle.trim() || isCreating) return;

    setIsCreating(true);
    try {
      await onCreateProject(newProjectTitle.trim(), selectedColor);
      setNewProjectTitle('');
      setShowColorPicker(false);
    } catch (error) {
      console.error('Failed to create project:', error);
    } finally {
      setIsCreating(false);
    }
  };

  // 드래그 시작
  const handleDragStart = (e: React.DragEvent, projectId: string) => {
    setDraggedId(projectId);
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', projectId);
    
    // 드래그 이미지 스타일링
    const target = e.target as HTMLElement;
    target.style.opacity = '0.5';
  };

  // 드래그 종료
  const handleDragEnd = (e: React.DragEvent) => {
    const target = e.target as HTMLElement;
    target.style.opacity = '1';
    setDraggedId(null);
    setDragOverId(null);
  };

  // 드래그 오버
  const handleDragOver = (e: React.DragEvent, projectId: string) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    if (projectId !== draggedId) {
      setDragOverId(projectId);
    }
  };

  // 드롭
  const handleDrop = async (e: React.DragEvent, targetId: string) => {
    e.preventDefault();
    
    if (!draggedId || draggedId === targetId) {
      setDraggedId(null);
      setDragOverId(null);
      return;
    }

    // 새 순서 계산
    const currentOrder = projects.map(p => p.id);
    const draggedIndex = currentOrder.indexOf(draggedId);
    const targetIndex = currentOrder.indexOf(targetId);

    if (draggedIndex === -1 || targetIndex === -1) return;

    // 배열에서 드래그된 항목 제거 후 타겟 위치에 삽입
    const newOrder = [...currentOrder];
    newOrder.splice(draggedIndex, 1);
    newOrder.splice(targetIndex, 0, draggedId);

    try {
      await onReorderProjects(newOrder);
    } catch (error) {
      console.error('Failed to reorder projects:', error);
    }

    setDraggedId(null);
    setDragOverId(null);
  };

  return (
    <div className="project-list">
      {/* 새 프로젝트 입력 */}
      <form className="new-project-form" onSubmit={handleCreateProject}>
        <div className="new-project-input-wrapper">
          <button
            type="button"
            className="color-picker-btn"
            style={{ backgroundColor: selectedColor }}
            onClick={() => setShowColorPicker(!showColorPicker)}
            title="색상 선택"
          />
          <input
            ref={inputRef}
            type="text"
            className="new-project-input"
            placeholder="새 프로젝트 추가..."
            value={newProjectTitle}
            onChange={(e) => setNewProjectTitle(e.target.value)}
            disabled={isCreating}
          />
          {newProjectTitle.trim() && (
            <button
              type="submit"
              className="add-project-btn"
              disabled={isCreating}
            >
              {isCreating ? '...' : '+'}
            </button>
          )}
        </div>
        
        {/* 색상 팔레트 */}
        {showColorPicker && (
          <div className="color-palette">
            {PROJECT_COLORS.map((color) => (
              <button
                key={color}
                type="button"
                className={`color-option ${selectedColor === color ? 'selected' : ''}`}
                style={{ backgroundColor: color }}
                onClick={() => {
                  setSelectedColor(color);
                  setShowColorPicker(false);
                  inputRef.current?.focus();
                }}
              />
            ))}
          </div>
        )}
      </form>

      {/* 활성 프로젝트 목록 */}
      <div className="projects-section">
        {projects.length === 0 ? (
          <div className="empty-projects">
            <span className="empty-icon">📁</span>
            <p>프로젝트가 없습니다</p>
            <p className="empty-hint">위에서 새 프로젝트를 만들어보세요</p>
          </div>
        ) : (
          <ul className="projects-items">
            {projects.map((project) => (
              <li
                key={project.id}
                className={`project-item ${selectedProjectId === project.id ? 'selected' : ''} ${dragOverId === project.id ? 'drag-over' : ''}`}
                draggable
                onDragStart={(e) => handleDragStart(e, project.id)}
                onDragEnd={handleDragEnd}
                onDragOver={(e) => handleDragOver(e, project.id)}
                onDrop={(e) => handleDrop(e, project.id)}
                onClick={() => onSelectProject(project)}
              >
                <span
                  className="project-color"
                  style={{ backgroundColor: project.color }}
                />
                <span className="project-title">{project.title}</span>
                <span className="drag-handle">⋮⋮</span>
              </li>
            ))}
          </ul>
        )}
      </div>

      {/* 아카이브된 프로젝트 */}
      {showArchived && archivedProjects.length > 0 && (
        <div className="archived-section">
          <div className="section-header">
            <span className="section-title">📦 아카이브</span>
            <span className="section-count">{archivedProjects.length}</span>
          </div>
          <ul className="projects-items archived">
            {archivedProjects.map((project) => (
              <li
                key={project.id}
                className={`project-item archived ${selectedProjectId === project.id ? 'selected' : ''}`}
                onClick={() => onSelectProject(project)}
              >
                <span
                  className="project-color"
                  style={{ backgroundColor: project.color, opacity: 0.5 }}
                />
                <span className="project-title">{project.title}</span>
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}
