// Todo 편집 패널
import { useState, useEffect } from 'react';
import type { ProjectTodo, ProjectTask, Project } from '../../types/work';
import './TodoEditPanel.css';

interface TodoEditPanelProps {
  todo: ProjectTodo | null;
  tasks: ProjectTask[];
  projects: Project[];
  onSave: (todo: ProjectTodo) => Promise<void>;
  onComplete: (todoId: string) => Promise<void>;
  onUndoComplete: (todoId: string) => Promise<void>;
  onDelete: (todoId: string) => Promise<void>;
  onClose: () => void;
}

export default function TodoEditPanel({
  todo,
  tasks,
  projects,
  onSave,
  onComplete,
  onUndoComplete,
  onDelete,
  onClose,
}: TodoEditPanelProps) {
  const [content, setContent] = useState('');
  const [taskId, setTaskId] = useState<string | null>(null);
  const [startAt, setStartAt] = useState('');
  const [endAt, setEndAt] = useState('');
  const [dueAt, setDueAt] = useState('');
  const [isAllDay, setIsAllDay] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  // 투두 변경 시 폼 초기화
  useEffect(() => {
    if (todo) {
      setContent(todo.content);
      setTaskId(todo.taskId);
      setStartAt(todo.start_at ? formatDateTimeLocal(todo.start_at) : '');
      setEndAt(todo.end_at ? formatDateTimeLocal(todo.end_at) : '');
      setDueAt(todo.due_at ? formatDateTimeLocal(todo.due_at) : '');
      setIsAllDay(todo.is_all_day);
    }
  }, [todo]);

  if (!todo) return null;

  const isDone = todo.is_done;

  // ISO 날짜를 datetime-local 형식으로 변환
  function formatDateTimeLocal(isoDate: string): string {
    if (!isoDate) return '';
    const date = new Date(isoDate);
    const tzOffset = date.getTimezoneOffset() * 60000;
    const localDate = new Date(date.getTime() - tzOffset);
    return localDate.toISOString().slice(0, 16);
  }

  // datetime-local 값을 ISO 문자열로 변환
  function toISOString(dateTimeLocal: string): string | null {
    if (!dateTimeLocal) return null;
    return new Date(dateTimeLocal).toISOString();
  }

  // 저장
  const handleSave = async () => {
    if (!content.trim() || isSaving) return;

    setIsSaving(true);
    try {
      await onSave({
        ...todo,
        content: content.trim(),
        taskId,
        start_at: toISOString(startAt),
        end_at: toISOString(endAt),
        due_at: toISOString(dueAt),
        is_all_day: isAllDay,
        updated_at: Date.now(),
      });
    } catch (error) {
      console.error('Failed to save todo:', error);
    } finally {
      setIsSaving(false);
    }
  };

  // 완료 토글
  const handleToggleComplete = async () => {
    try {
      if (isDone) {
        await onUndoComplete(todo.id);
      } else {
        await onComplete(todo.id);
      }
    } catch (error) {
      console.error('Failed to toggle todo completion:', error);
    }
  };

  // 삭제
  const handleDelete = async () => {
    try {
      await onDelete(todo.id);
      onClose();
    } catch (error) {
      console.error('Failed to delete todo:', error);
    }
  };

  // 태스크 정보 가져오기
  const getTaskInfo = (tid: string | null): { name: string; color: string } => {
    if (!tid) return { name: '미분류', color: '#64748b' };
    const task = tasks.find(t => t.id === tid);
    if (!task) return { name: '미분류', color: '#64748b' };
    const project = projects.find(p => p.id === task.projectId);
    return { name: task.title, color: project?.color || '#64748b' };
  };

  const taskInfo = getTaskInfo(taskId);
  const activeTasks = tasks.filter(t => t.status === 'ACTIVE');

  return (
    <div className="todo-edit-panel">
      <div className="panel-header">
        <div className="panel-title-wrapper">
          <span 
            className="task-indicator" 
            style={{ backgroundColor: taskInfo.color }}
          />
          <h3>투두 편집</h3>
        </div>
        <button className="close-btn" onClick={onClose}>×</button>
      </div>

      <div className="panel-content">
        {/* 상태 표시 */}
        {isDone && (
          <div className="status-badge done">
            ✓ 완료됨 ({todo.completed_at && new Date(todo.completed_at).toLocaleDateString('ko-KR')})
          </div>
        )}

        {/* 내용 */}
        <div className="form-group">
          <label>내용</label>
          <textarea
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="투두 내용"
            rows={3}
          />
        </div>

        {/* 태스크 선택 */}
        <div className="form-group">
          <label>태스크</label>
          <select
            value={taskId || ''}
            onChange={(e) => setTaskId(e.target.value || null)}
          >
            <option value="">미분류</option>
            {activeTasks.map((task) => (
              <option key={task.id} value={task.id}>
                {task.title}
              </option>
            ))}
          </select>
        </div>

        {/* 종일 여부 */}
        <div className="form-group checkbox-group">
          <label>
            <input
              type="checkbox"
              checked={isAllDay}
              onChange={(e) => setIsAllDay(e.target.checked)}
            />
            종일
          </label>
        </div>

        {/* 시작일 */}
        <div className="form-group">
          <label>시작일</label>
          <input
            type={isAllDay ? 'date' : 'datetime-local'}
            value={isAllDay && startAt ? startAt.slice(0, 10) : startAt}
            onChange={(e) => setStartAt(e.target.value)}
          />
        </div>

        {/* 종료일 */}
        <div className="form-group">
          <label>종료일</label>
          <input
            type={isAllDay ? 'date' : 'datetime-local'}
            value={isAllDay && endAt ? endAt.slice(0, 10) : endAt}
            onChange={(e) => setEndAt(e.target.value)}
          />
        </div>

        {/* 마감일 */}
        <div className="form-group">
          <label>마감일</label>
          <input
            type={isAllDay ? 'date' : 'datetime-local'}
            value={isAllDay && dueAt ? dueAt.slice(0, 10) : dueAt}
            onChange={(e) => setDueAt(e.target.value)}
          />
        </div>

        {/* 메타 정보 */}
        <div className="meta-info">
          <span>생성: {new Date(todo.created_at).toLocaleDateString('ko-KR')}</span>
          <span>수정: {new Date(todo.updated_at).toLocaleDateString('ko-KR')}</span>
        </div>
      </div>

      <div className="panel-footer">
        <button
          className={`complete-toggle-btn ${isDone ? 'done' : ''}`}
          onClick={handleToggleComplete}
        >
          {isDone ? '완료 취소' : '✓ 완료'}
        </button>
        <button
          className="delete-btn"
          onClick={() => setShowDeleteConfirm(true)}
        >
          삭제
        </button>
        <button
          className="save-btn"
          onClick={handleSave}
          disabled={!content.trim() || isSaving}
        >
          {isSaving ? '저장 중...' : '저장'}
        </button>
      </div>

      {/* 삭제 확인 다이얼로그 */}
      {showDeleteConfirm && (
        <div className="confirm-overlay">
          <div className="confirm-dialog">
            <h4>투두 삭제</h4>
            <p>
              이 투두를 삭제하시겠습니까?
              <br />
              이 작업은 되돌릴 수 없습니다.
            </p>
            <div className="confirm-actions">
              <button
                className="cancel-btn"
                onClick={() => setShowDeleteConfirm(false)}
              >
                취소
              </button>
              <button
                className="confirm-delete-btn"
                onClick={handleDelete}
              >
                삭제
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
