// Project 편집 패널
import { useState, useEffect } from 'react';
import type { Project } from '../../types/work';
import { createProjectSnapshot } from '../../stores/workFirestore';
import './ProjectEditPanel.css';

interface ProjectEditPanelProps {
  project: Project | null;
  onSave: (project: Project) => Promise<void>;
  onArchive: (projectId: string) => Promise<void>;
  onDelete: (projectId: string) => Promise<void>;
  onClose: () => void;
}

const PROJECT_COLORS = [
  '#a5b4fc', '#818cf8', '#6366f1',
  '#c4b5fd', '#a78bfa', '#8b5cf6',
  '#f0abfc', '#e879f9', '#d946ef',
  '#fda4af', '#fb7185', '#f43f5e',
  '#fcd34d', '#fbbf24', '#f59e0b',
  '#86efac', '#4ade80', '#22c55e',
  '#67e8f9', '#22d3ee', '#06b6d4',
  '#94a3b8', '#64748b', '#475569',
];

export default function ProjectEditPanel({
  project,
  onSave,
  onArchive,
  onDelete,
  onClose,
}: ProjectEditPanelProps) {
  const [title, setTitle] = useState('');
  const [color, setColor] = useState('#a5b4fc');
  const [startAt, setStartAt] = useState('');
  const [endAt, setEndAt] = useState('');
  const [dueAt, setDueAt] = useState('');
  const [isAllDay, setIsAllDay] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [isCreatingSnapshot, setIsCreatingSnapshot] = useState(false);
  const [snapshotUrl, setSnapshotUrl] = useState<string | null>(null);
  const [showSnapshotSuccess, setShowSnapshotSuccess] = useState(false);

  // 프로젝트 변경 시 폼 초기화
  useEffect(() => {
    if (project) {
      setTitle(project.title);
      setColor(project.color);
      setStartAt(project.start_at ? formatDateTimeLocal(project.start_at) : '');
      setEndAt(project.end_at ? formatDateTimeLocal(project.end_at) : '');
      setDueAt(project.due_at ? formatDateTimeLocal(project.due_at) : '');
      setIsAllDay(project.is_all_day);
      setSnapshotUrl(null);
      setShowSnapshotSuccess(false);
    }
  }, [project]);

  if (!project) return null;

  const isArchived = project.status === 'ARCHIVED';

  // ISO 날짜를 datetime-local 형식으로 변환
  function formatDateTimeLocal(isoDate: string): string {
    if (!isoDate) return '';
    const date = new Date(isoDate);
    const tzOffset = date.getTimezoneOffset() * 60000;
    const localDate = new Date(date.getTime() - tzOffset);
    return localDate.toISOString().slice(0, 16);
  }

  // datetime-local 값을 ISO 문자열로 변환
  function toISOString(dateTimeLocal: string): string | null {
    if (!dateTimeLocal) return null;
    return new Date(dateTimeLocal).toISOString();
  }

  // 저장
  const handleSave = async () => {
    if (!title.trim() || isSaving) return;

    setIsSaving(true);
    try {
      await onSave({
        ...project,
        title: title.trim(),
        color,
        start_at: toISOString(startAt),
        end_at: toISOString(endAt),
        due_at: toISOString(dueAt),
        is_all_day: isAllDay,
        updated_at: Date.now(),
      });
    } catch (error) {
      console.error('Failed to save project:', error);
    } finally {
      setIsSaving(false);
    }
  };

  // 스냅샷 생성
  const handleCreateSnapshot = async () => {
    if (isCreatingSnapshot) return;

    setIsCreatingSnapshot(true);
    try {
      const snapshot = await createProjectSnapshot(project.id, { includeCompleted: false });
      const shareUrl = `${window.location.origin}${window.location.pathname}#/share/${snapshot.token}`;
      setSnapshotUrl(shareUrl);
      setShowSnapshotSuccess(true);
    } catch (error) {
      console.error('Failed to create snapshot:', error);
      alert('스냅샷 생성에 실패했습니다.');
    } finally {
      setIsCreatingSnapshot(false);
    }
  };

  // 링크 복사
  const handleCopyLink = async () => {
    if (!snapshotUrl) return;
    try {
      await navigator.clipboard.writeText(snapshotUrl);
      alert('링크가 복사되었습니다!');
    } catch (error) {
      console.error('Failed to copy link:', error);
      // 폴백: 프롬프트로 표시
      prompt('링크를 복사하세요:', snapshotUrl);
    }
  };

  // 아카이브
  const handleArchive = async () => {
    try {
      await onArchive(project.id);
      onClose();
    } catch (error) {
      console.error('Failed to archive project:', error);
    }
  };

  // 영구 삭제
  const handleDelete = async () => {
    try {
      await onDelete(project.id);
      onClose();
    } catch (error) {
      console.error('Failed to delete project:', error);
    }
  };

  return (
    <div className="project-edit-panel">
      <div className="panel-header">
        <h3>프로젝트 편집</h3>
        <button className="close-btn" onClick={onClose}>×</button>
      </div>

      <div className="panel-content">
        {/* 제목 */}
        <div className="form-group">
          <label>제목</label>
          <input
            type="text"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="프로젝트 제목"
            disabled={isArchived}
          />
        </div>

        {/* 색상 */}
        <div className="form-group">
          <label>색상</label>
          <div className="color-grid">
            {PROJECT_COLORS.map((c) => (
              <button
                key={c}
                type="button"
                className={`color-btn ${color === c ? 'selected' : ''}`}
                style={{ backgroundColor: c }}
                onClick={() => setColor(c)}
                disabled={isArchived}
              />
            ))}
          </div>
        </div>

        {/* 종일 여부 */}
        <div className="form-group checkbox-group">
          <label>
            <input
              type="checkbox"
              checked={isAllDay}
              onChange={(e) => setIsAllDay(e.target.checked)}
              disabled={isArchived}
            />
            종일
          </label>
        </div>

        {/* 시작일 */}
        <div className="form-group">
          <label>시작일</label>
          <input
            type={isAllDay ? 'date' : 'datetime-local'}
            value={isAllDay && startAt ? startAt.slice(0, 10) : startAt}
            onChange={(e) => setStartAt(e.target.value)}
            disabled={isArchived}
          />
        </div>

        {/* 종료일 */}
        <div className="form-group">
          <label>종료일</label>
          <input
            type={isAllDay ? 'date' : 'datetime-local'}
            value={isAllDay && endAt ? endAt.slice(0, 10) : endAt}
            onChange={(e) => setEndAt(e.target.value)}
            disabled={isArchived}
          />
        </div>

        {/* 마감일 */}
        <div className="form-group">
          <label>마감일</label>
          <input
            type={isAllDay ? 'date' : 'datetime-local'}
            value={isAllDay && dueAt ? dueAt.slice(0, 10) : dueAt}
            onChange={(e) => setDueAt(e.target.value)}
            disabled={isArchived}
          />
        </div>

        {/* 생성일/수정일 정보 */}
        <div className="meta-info">
          <span>생성: {new Date(project.created_at).toLocaleDateString('ko-KR')}</span>
          <span>수정: {new Date(project.updated_at).toLocaleDateString('ko-KR')}</span>
        </div>

        {/* 공유 스냅샷 */}
        {!isArchived && (
          <div className="share-section">
            <label>공유</label>
            {showSnapshotSuccess && snapshotUrl ? (
              <div className="snapshot-success">
                <p>스냅샷이 생성되었습니다!</p>
                <div className="snapshot-url">
                  <input
                    type="text"
                    value={snapshotUrl}
                    readOnly
                    onClick={(e) => (e.target as HTMLInputElement).select()}
                  />
                  <button
                    type="button"
                    className="copy-btn"
                    onClick={handleCopyLink}
                  >
                    복사
                  </button>
                </div>
                <button
                  type="button"
                  className="new-snapshot-btn"
                  onClick={() => {
                    setShowSnapshotSuccess(false);
                    setSnapshotUrl(null);
                  }}
                >
                  새 스냅샷 생성
                </button>
              </div>
            ) : (
              <button
                type="button"
                className="share-btn"
                onClick={handleCreateSnapshot}
                disabled={isCreatingSnapshot}
              >
                {isCreatingSnapshot ? '생성 중...' : '📤 공유 스냅샷 생성'}
              </button>
            )}
            <p className="share-hint">
              현재 프로젝트 상태를 스냅샷으로 저장하고 공유 링크를 생성합니다.
            </p>
          </div>
        )}
      </div>

      <div className="panel-footer">
        {isArchived ? (
          <>
            <button
              className="delete-btn"
              onClick={() => setShowDeleteConfirm(true)}
            >
              영구 삭제
            </button>
          </>
        ) : (
          <>
            <button
              className="archive-btn"
              onClick={handleArchive}
            >
              아카이브
            </button>
            <button
              className="save-btn"
              onClick={handleSave}
              disabled={!title.trim() || isSaving}
            >
              {isSaving ? '저장 중...' : '저장'}
            </button>
          </>
        )}
      </div>

      {/* 삭제 확인 다이얼로그 */}
      {showDeleteConfirm && (
        <div className="confirm-overlay">
          <div className="confirm-dialog">
            <h4>프로젝트 영구 삭제</h4>
            <p>
              이 프로젝트와 하위 모든 태스크, 투두가 영구적으로 삭제됩니다.
              <br />
              이 작업은 되돌릴 수 없습니다.
            </p>
            <div className="confirm-actions">
              <button
                className="cancel-btn"
                onClick={() => setShowDeleteConfirm(false)}
              >
                취소
              </button>
              <button
                className="confirm-delete-btn"
                onClick={handleDelete}
              >
                삭제
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
